/// `Some(None)` for an explicit JSON `null`, so a decoded request keeps the
/// difference between "absent" and "clear".
fn double_option<'de, T, D>(de: D) -> Result<Option<Option<T>>, D::Error>
where
    T: Deserialize<'de>,
    D: Deserializer<'de>,
{
    Option::<T>::deserialize(de).map(Some)
}

